// Ops call him John; leads config still says Giannis — same person.
function displayName(key) {
  if (key === 'giannis') return 'John';
  return teamName(key) || key || '';
}
function prettyPerson(name) {
  var s = String(name || '').trim().replace(/\s+/g, ' ');
  if (!s) return '';
  // Meta sometimes dumps ALL CAPS or all lowercase.
  if (s === s.toUpperCase() || s === s.toLowerCase()) {
    return s.toLowerCase().replace(/(^|[\s'\-])(\S)/g, function (_, a, b) { return a + b.toUpperCase(); });
  }
  return s;
}
function pipelinePos(l) {
  var i = IDX[l && l.stage];
  if (i === undefined) return LABEL[l && l.stage] || (l && l.stage) || '';
  return 'Step ' + (i + 1) + ' of ' + STAGES.length + ' · ' + (LABEL[l.stage] || l.stage);
}
function slaLabel(l) {
  var st = slaState(l);
  var lim = Number(cfg.slaFirstContactHours || 4);
  if (st === 'late') return 'Still not contacted · overdue (aim: within ' + lim + 'h)';
  if (st === 'soon') return 'Still not contacted · due soon (aim: within ' + lim + 'h)';
  return '';
}

