var NEXT={new:'Call or email them',to_contact:'Call or email them',contacted:'Qualify the property',qualified:'Book a viewing',viewing:'Send a proposal',proposal:'Send the contract',contract_sent:'Chase the signature',signed:'Start onboarding',onboarding:'Go live'};
var LABEL={new:'New',to_contact:'To contact',contacted:'Contacted',qualified:'Qualified',viewing:'Viewing',proposal:'Proposal',contract_sent:'Contract sent',signed:'Signed',onboarding:'Onboarding'};
var STEPS=['new','to_contact','contacted','qualified','viewing','proposal','contract_sent','signed','onboarding','live'];
function paint(pack){
  var mine=pack.mine||[];
  if(countEl) countEl.textContent=String(mine.length);
  if(!slot) return;
  if(!pack.me || !mine.length){ slot.style.display='none'; return; }
  if(empty && empty.parentNode) empty.parentNode.removeChild(empty);
  slot.style.display='';
  slot.innerHTML='<h3><span class="dot" style="background:var(--gold)"></span>Open leads <span class="cnt">'+mine.length+'</span></h3>'+
    mine.slice(0,10).map(function(l){
      var act=NEXT[l.stage]||'Open the ticket';
      var si=STEPS.indexOf(l.stage);
      var pipe=si>=0?('Step '+(si+1)+' of 10 · '+(LABEL[l.stage]||l.stage)):(LABEL[l.stage]||l.stage);
      var raw=String(l.full_name||'').trim().replace(/\s+/g,' ');
      var name=!raw?'(no name)':(raw===raw.toUpperCase()||raw===raw.toLowerCase())?raw.toLowerCase().replace(/(^|[\s'\-])(\S)/g,function(_,a,b){return a+b.toUpperCase();}):raw;
      var sub=pipe+(l.property_address?(' · '+l.property_address):'');
      return '<div class="home-row" style="cursor:pointer" onclick="ldGoTask('+l.id+')"><span class="dot" style="background:var(--gold)"></span><div class="rl"><b>'+esc(name)+'</b><div class="meta">Lead · '+esc(sub)+'</div></div><span class="lnk">'+esc(act)+' →</span></div>';
    }).join('')+(mine.length>10?'<div class="home-empty">+'+(mine.length-10)+' more on Leads</div>':'');
}
